using System;
using System.Runtime.Serialization;

namespace LiteMock
{
	/// <summary>
	/// Represents an error occuring within a mock object.
	/// </summary>
	[global::System.Serializable]
	public class MockException : Exception
	{
		public MockException() { }
		public MockException(string message) : base(message) { }
		public MockException(string message, Exception inner) : base(message, inner) { }
		protected MockException(SerializationInfo info, StreamingContext context) : base(info, context) { }
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Runtime.Remoting.Messaging;
using System.Reflection;
using System.Runtime.Serialization;

namespace LiteMock
{
	/// <summary>
	/// When a call occurs a specified exception will be thrown.
	/// </summary>
	class ExceptionBehaviour : CallBehaviour
	{
		Exception exception;
		public ExceptionBehaviour(Exception exception)
		{
			this.exception = exception;
		}

		public override IMessage Process(MethodCallMessageWrapper mc)
		{
			return new ReturnMessage(exception, mc);
		}
	}
}

﻿using System;
using System.Collections.Generic;
