using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Runtime.Remoting.Messaging;
using System.Reflection;
using System.Runtime.Serialization;

namespace LiteMock
{
	/// <summary>
	/// When a call occurs the arguments are checked against some pre-defined 
	/// set and an exception is thrown if they do not match.
	/// </summary>
	class CheckArgumentsBehaviour : IgnoreBehaviour
	{
		object[] expectedArgs;

		public CheckArgumentsBehaviour(object[] expectedArgs)
		{
			this.expectedArgs = expectedArgs;
		}

		public override IMessage Process(MethodCallMessageWrapper mc)
		{
			if (!mc.InArgs.SequenceEqual(expectedArgs))
			{
				string[] expected = expectedArgs.Select(o => o.ToString()).ToArray();
				string[] actual = mc.InArgs.Select(o => o.ToString()).ToArray();
				string message = String.Format("Expected arguments {0} but found {1}", String.Join(", ", expected), String.Join(", ", actual));
				var exception = new MockException(message);
				return new ExceptionBehaviour(exception).Process(mc);
			}
			return base.Process(mc);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Runtime.Remoting.Messaging;
using System.Reflection;
using System.Runtime.Serialization;

namespace LiteMock
{
	/// <summary>
	/// Defines an action to be performed when encountering a method call 
	/// matching a particular profile.
	/// </summary>
	abstract class CallBehaviour
	{
		/// <summary>
		/// Method profile to be matched.
		/// </summary>
		public Predicate<MethodCallMessageWrapper> Profile { get; set; }

		/// <summary>
		/// Action to perform.
		/// </summary>
		/// <param name="mc"></param>
		/// <returns></returns>
		public abstract IMessage Process(MethodCallMessageWrapper mc);
	}
}

﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Runtime.Remoting.Messaging;
using System.Runtime.Remoting.Proxies;
using System.Reflection;
using System.Runtime.Serialization;

namespace LiteMock
{
	/// <summary>
	/// Proxy providing mocking functionality.
	/// </summary>
	class MockingProxy : RealProxy
	{
		public CallBehaviour CatchAllBehaviour = new ExceptionBehaviour(new MockException("Unexpected call"));
		public readonly List<CallBehaviour> CallBehaviours = new List<CallBehaviour>();
		
		public MockingProxy(Type type) : base(type) { }

		public override IMessage Invoke(IMessage msg)
		{
			MethodCallMessageWrapper mc = new MethodCallMessageWrapper((IMethodCallMessage)msg);

			CallBehaviour behaviour = CallBehaviours.FirstOrDefault(i => i.Profile(mc));

			if (behaviour != null)
			{
				return behaviour.Process(mc);
			}

			return CatchAllBehaviour.Process(mc);
		}
	}
}

